24	/**
25	 The {@link Safelist}-based HTML cleaner. Use to ensure that end-user provided HTML contains only the elements and attributes
26	 that you are expecting; no junk, and no cross-site scripting attacks!
27	 <p>
28	 The HTML cleaner parses the input as HTML and then runs it through a safelist, so the output HTML can only contain
29	 HTML that is allowed by the safelist.
30	 </p>
31	 <p>
32	 It is assumed that the input HTML is a body fragment; the clean methods only pull from the source's body, and the
33	 canned safelists only allow body-contained tags.
34	 </p>
35	 <p>
36	 Rather than interacting directly with a Cleaner object, generally see the {@code clean} methods in {@link org.jsoup.Jsoup}.
37	 </p>
38	 <p>
39	 A Cleaner may be reused across multiple documents and shared across concurrent threads once its {@link Safelist} has
40	 been configured. The cleaner uses the supplied safelist directly, so later safelist changes affect later cleaning
41	 calls. If you need a variant of an existing configuration, use {@link Safelist#Safelist(Safelist)} to make a copy.
42	 </p>
43	 */
44	public class Cleaner {
45	    private final Safelist safelist;
46	
47	    /**
48	     Create a new cleaner, that sanitizes documents using the supplied safelist.
49	     @param safelist safe-list to clean with
50	     */
51	    public Cleaner(Safelist safelist) {
52	        Validate.notNull(safelist);
53	        this.safelist = safelist;
54	    }
55	
56	    /**
57	     Creates a new, clean document, from the original dirty document, containing only elements allowed by the safelist.
58	     The original document is not modified. Only elements from the dirty document's <code>body</code> are used. The
59	     OutputSettings of the original document are cloned into the clean document.
60	     @param dirtyDocument Untrusted base document to clean.
61	     @return cleaned document.
62	     */
63	    public Document clean(Document dirtyDocument) {
64	        Validate.notNull(dirtyDocument);
65	
66	        Document clean = Document.createShell(dirtyDocument.baseUri());
67	        copySafeNodes(dirtyDocument.body(), clean.body());
68	        clean.outputSettings(dirtyDocument.outputSettings().clone());
69	
70	        return clean;
71	    }
72	
73	    /**
74	     Determines if the input document's <b>body</b> is valid, against the safelist. It is considered valid if all the
75	     tags and attributes in the input HTML are allowed by the safelist, and that there is no content in the
76	     <code>head</code>.
77	     <p>
78	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
79	     output of this method, the input document <b>must always</b> be normalized using a method such as
80	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
81	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
82	     differences between how a given browser and how jsoup parses the input HTML are normalized.
83	     </p>
84	     <p>Example:
85	     <pre>{@code
86	     Document inputDoc = Jsoup.parse(inputHtml);
87	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
88	     boolean isValid = cleaner.isValid(inputDoc);
89	     Document normalizedDoc = cleaner.clean(inputDoc);
90	     }</pre>
91	     </p>
92	     @param dirtyDocument document to test
93	     @return true if no tags or attributes need to be removed; false if they do
94	     */
95	    public boolean isValid(Document dirtyDocument) {
96	        Validate.notNull(dirtyDocument);
97	
98	        Document clean = Document.createShell(dirtyDocument.baseUri());
99	        int numDiscarded = copySafeNodes(dirtyDocument.body(), clean.body());
100	        return numDiscarded == 0
101	            && dirtyDocument.head().childNodes().isEmpty(); // because we only look at the body, but we start from a shell, make sure there's nothing in the head
102	    }
103	
104	    /**
105	     Determines if the input document's <b>body HTML</b> is valid, against the safelist. It is considered valid if all
106	     the tags and attributes in the input HTML are allowed by the safelist.
107	     <p>
108	     This method is intended to be used in a user interface as a validator for user input. Note that regardless of the
109	     output of this method, the input document <b>must always</b> be normalized using a method such as
110	     {@link #clean(Document)}, and the result of that method used to store or serialize the document before later reuse
111	     such as presentation to end users. This ensures that enforced attributes are set correctly, and that any
112	     differences between how a given browser and how jsoup parses the input HTML are normalized.
113	     </p>
114	     <p>Example:
115	     <pre>{@code
116	     Document inputDoc = Jsoup.parse(inputHtml);
117	     Cleaner cleaner = new Cleaner(Safelist.relaxed());
118	     boolean isValid = cleaner.isValidBodyHtml(inputHtml);
119	     Document normalizedDoc = cleaner.clean(inputDoc);
120	     }</pre>
121	     </p>
122	     @param bodyHtml HTML fragment to test
123	     @return true if no tags or attributes need to be removed; false if they do
124	     */
125	    public boolean isValidBodyHtml(String bodyHtml) {
126	        String baseUri = (safelist.preserveRelativeLinks()) ? DummyUri : ""; // fake base URI to allow relative URLs to remain valid
127	        Document clean = Document.createShell(baseUri);
128	        Document dirty = Document.createShell(baseUri);
129	        ParseErrorList errorList = ParseErrorList.tracking(1);
130	        List<Node> nodes = Parser.parseFragment(bodyHtml, dirty.body(), baseUri, errorList);
131	        dirty.body().insertChildren(0, nodes);
132	        int numDiscarded = copySafeNodes(dirty.body(), clean.body());
133	        return numDiscarded == 0 && errorList.isEmpty();
134	    }
135	
136	    /**
137	     Iterates the input and copies trusted nodes (tags, attributes, text) into the destination.
138	     */
139	    private final class CleaningVisitor implements NodeVisitor {
140	        private int numDiscarded = 0;
141	        private final Element root;
142	        private Element destination; // current element to append nodes to
143	
144	        private CleaningVisitor(Element root, Element destination) {
145	            this.root = root;
146	            this.destination = destination;
147	        }
148	
149	        @Override public void head(Node source, int depth) {
150	            if (source instanceof Element) {
151	                Element sourceEl = (Element) source;
152	
153	                if (safelist.isSafeTag(sourceEl.normalName())) { // safe, clone and copy safe attrs
154	                    ElementMeta meta = createSafeElement(sourceEl);
155	                    Element destChild = meta.el;
156	                    destination.appendChild(destChild);
157	
158	                    numDiscarded += meta.numAttribsDiscarded;
159	                    destination = destChild;
160	                } else if (source != root) { // not a safe tag, so don't add. don't count root against discarded.
161	                    numDiscarded++;
162	                }
163	            } else if (source instanceof TextNode) {
164	                TextNode sourceText = (TextNode) source;
165	                appendText(destination, sourceText.getWholeText());
166	            } else if (source instanceof DataNode && safelist.isSafeTag(source.parent().normalName())) {
167	                DataNode sourceData = (DataNode) source;
168	                DataNode destData = new DataNode(sourceData.getWholeData());
169	                destination.appendChild(destData);
170	            } else { // else, we don't care about comments, xml proc instructions, etc
171	                numDiscarded++;
172	            }
173	        }
174	
175	        @Override public void tail(Node source, int depth) {
176	            if (source instanceof Element && safelist.isSafeTag(source.normalName())) {
177	                destination = destination.parent(); // would have descended, so pop destination stack
178	            }
179	        }
180	
181	        /**
182	         Appends source text to the destination. When the preceding source node was discarded (leaving this text
183	         directly adjacent to an earlier text node in the output), the runs are joined into one text node. This
184	         mirrors how the serialized output is re-parsed later -- adjacent text nodes are merged then -- and keeps
185	         whitespace normalization from collapsing across the join differently on a second clean.
186	         */
187	        private void appendText(Element dest, String text) {
188	            Node last = dest.lastChild();
189	            if (last != null && last.getClass() == TextNode.class) {
190	                TextNode lastText = (TextNode) last;
191	                lastText.text(lastText.getWholeText() + text);
192	            } else {
193	                dest.appendChild(new TextNode(text));
194	            }
195	        }
196	    }
197	
198	    private int copySafeNodes(Element source, Element dest) {
199	        CleaningVisitor cleaningVisitor = new CleaningVisitor(source, dest);
200	        cleaningVisitor.traverse(source);
201	        return cleaningVisitor.numDiscarded;
202	    }
203	
204	    private ElementMeta createSafeElement(Element sourceEl) {
205	        Element dest = sourceEl.shallowClone(); // reuses tag, clones attributes and preserves any user data
206	        String sourceTag = sourceEl.tagName();
207	        Attributes destAttrs = dest.attributes();
208	        dest.clearAttributes(); // clear all non-internal attributes, ready for safe copy
209	
210	        int numDiscarded = 0;
211	        Attributes sourceAttrs = sourceEl.attributes();
212	        for (Attribute sourceAttr : sourceAttrs) {
213	            if (safelist.isSafeAttribute(sourceTag, sourceEl, sourceAttr)) { // will keep this attr
214	                String key = sourceAttr.getKey();
215	                String value = sourceAttr.getValue();
216	
217	                if (safelist.shouldAbsUrl(sourceTag, key)) { // configured to make absolute urls for this key (href)
218	                    if (Safelist.multiValueUrlAttribute(key)) { // srcset etc: resolve each candidate independently
219	                        value = resolveCandidateUrls(sourceEl, value);
220	                    } else {
221	                        value = sourceEl.absUrl(key);
222	                        if (value.isEmpty()) // could not be made abs; leave as-is to allow custom unknown protocols
223	                            value = sourceAttr.getValue();
224	                    }
225	                }
226	                Range.AttributeRange range = sourceAttrs.sourceRange(key);
227	                destAttrs.put(key, value);
228	                NodeInternals.attributeRange(destAttrs, key, range);
229	            } else
230	                numDiscarded++;
231	        }
232	
233	        Attributes enforcedAttrs = safelist.getEnforcedAttributes(sourceTag);
234	        // special case for <a href rel=nofollow>, only apply to external links:
235	        if (sourceEl.nameIs("a") && enforcedAttrs.get("rel").equals("nofollow")) {
236	            // only a link whose href actually passed the safelist (and so is retained) can be same-site; a dropped or
237	            // unsafe href must keep the enforced nofollow, otherwise cleaning the href-less output a second time
238	            // would add it and break idempotency
239	            Attribute hrefAttr = sourceEl.attribute("href");
240	            if (hrefAttr != null && safelist.isSafeAttribute(sourceTag, sourceEl, hrefAttr)) {
241	                String href = sourceEl.absUrl("href");
242	                if (!href.isEmpty()) {
243	                    try {
244	                        URL baseUrl = new URL(sourceEl.baseUri());
245	                        URL linkUrl = new URL(href);
246	                        String baseHost = baseUrl.getHost();
247	                        if (!baseHost.isEmpty() && baseHost.equalsIgnoreCase(linkUrl.getHost())) // same site, so don't set the nofollow
248	                            enforcedAttrs.remove("rel");
249	                    } catch (MalformedURLException ignored) {}
250	                }
251	            }
252	        }
253	
254	        // apply enforced attributes case-insensitively, so a preserved-case source attr is canonicalized to the enforced key
255	        for (Attribute enforcedAttr : enforcedAttrs) {
256	            destAttrs.removeIgnoreCase(enforcedAttr.getKey());
257	            destAttrs.put(enforcedAttr.getKey(), enforcedAttr.getValue());
258	        }
259	        dest.attributes().addAll(destAttrs); // re-attach, if removed in clear
260	        return new ElementMeta(dest, numDiscarded);
261	    }
262	
263	    private static boolean isHtmlWhitespace(char c) {
264	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
265	    }
266	
267	    /**
268	     Resolve each comma-separated candidate URL (e.g. in a {@code srcset} attribute) against the element's base URI,
269	     preserving the candidate descriptors and the original separators. Returns the source value untouched when none of
270	     the candidates changed, so that already-normalized output is stable on a second clean.
271	     */
272	    private String resolveCandidateUrls(Element sourceEl, String value) {
273	        String baseUri = sourceEl.baseUri();
274	        int len = value.length();
275	        StringBuilder out = null;
276	        int start = 0;
277	        for (int i = 0; i <= len; i++) {
278	            if (i != len && value.charAt(i) != ',') continue;
279	
280	            String segment = value.substring(start, i);
281	            int segLen = segment.length();
282	            int urlStart = 0;
283	            while (urlStart < segLen && isHtmlWhitespace(segment.charAt(urlStart))) urlStart++;
284	            int urlEnd = urlStart;
285	            while (urlEnd < segLen && !isHtmlWhitespace(segment.charAt(urlEnd))) urlEnd++;
286	
287	            boolean changed = false;
288	            if (urlEnd > urlStart) {
289	                String candidate = segment.substring(urlStart, urlEnd);
290	                String resolved = StringUtil.resolve(baseUri, candidate);
291	                if (resolved.isEmpty()) resolved = candidate; // mirror single-URL behavior: leave unresolvable as-is
292	                if (!resolved.equals(candidate)) {
293	                    changed = true;
294	                    if (out == null) {
295	                        out = new StringBuilder(len + 16);
296	                        out.append(value, 0, start); // everything before the first changed candidate, flushed once
297	                    }
298	                    out.append(segment, 0, urlStart).append(resolved).append(segment, urlEnd, segLen);
299	                }
300	            }
301	            if (!changed && out != null) out.append(segment);
302	            if (out != null && i < len) out.append(',');
303	
304	            start = i + 1;
305	        }
306	        return out == null ? value : out.toString();
307	    }
308	
309	    private static class ElementMeta {
310	        Element el;
311	        int numAttribsDiscarded;
312	
313	        ElementMeta(Element el, int numAttribsDiscarded) {
314	            this.el = el;
315	            this.numAttribsDiscarded = numAttribsDiscarded;
316	        }
317	    }
318	
319	}
