166	     This safelist allows a full range of text and structural body HTML: <code>a, b, blockquote, br, caption, cite,
167	     code, col, colgroup, dd, div, dl, dt, em, h1, h2, h3, h4, h5, h6, i, img, li, ol, p, pre, q, small, span, strike, strong, sub,
168	     sup, table, tbody, td, tfoot, th, thead, tr, u, ul</code>
169	     <p>
170	     Links do not have an enforced <code>rel=nofollow</code> attribute, but you can add that if desired.
171	     </p>
172	
173	     @return safelist
174	     */
175	    public static Safelist relaxed() {
176	        return new Safelist()
177	                .addTags(
178	                        "a", "b", "blockquote", "br", "caption", "cite", "code", "col",
179	                        "colgroup", "dd", "div", "dl", "dt", "em", "h1", "h2", "h3", "h4", "h5", "h6",
180	                        "i", "img", "li", "ol", "p", "pre", "q", "small", "span", "strike", "strong",
181	                        "sub", "sup", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "u",
182	                        "ul")
183	
184	                .addAttributes("a", "href", "title")
185	                .addAttributes("blockquote", "cite")
186	                .addAttributes("col", "span", "width")
187	                .addAttributes("colgroup", "span", "width")
188	                .addAttributes("img", "align", "alt", "height", "src", "title", "width")
