206	    /**
207	     Create a new, empty safelist. Generally it will be better to start with a default prepared safelist instead.
208	
209	     @see #basic()
210	     @see #basicWithImages()
211	     @see #simpleText()
212	     @see #relaxed()
213	     */
214	    public Safelist() {
215	        tagNames = new HashSet<>();
216	        attributes = new HashMap<>();
217	        enforcedAttributes = new HashMap<>();
218	        protocols = new HashMap<>();
219	        preserveRelativeLinks = false;
220	    }
