222	    /**
223	     Deep copy an existing Safelist to a new Safelist.
224	     @param copy the Safelist to copy
225	     */
226	    public Safelist(Safelist copy) {
227	        this();
228	        tagNames.addAll(copy.tagNames);
229	        for (Map.Entry<TagName, Set<AttributeKey>> copyTagAttributes : copy.attributes.entrySet()) {
230	            attributes.put(copyTagAttributes.getKey(), new HashSet<>(copyTagAttributes.getValue()));
231	        }
232	        for (Map.Entry<TagName, Map<AttributeKey, AttributeValue>> enforcedEntry : copy.enforcedAttributes.entrySet()) {
233	            enforcedAttributes.put(enforcedEntry.getKey(), new HashMap<>(enforcedEntry.getValue()));
234	        }
235	        for (Map.Entry<TagName, Map<AttributeKey, Set<Protocol>>> protocolsEntry : copy.protocols.entrySet()) {
236	            Map<AttributeKey, Set<Protocol>> attributeProtocolsCopy = new HashMap<>();
237	            for (Map.Entry<AttributeKey, Set<Protocol>> attributeProtocols : protocolsEntry.getValue().entrySet()) {
238	                attributeProtocolsCopy.put(attributeProtocols.getKey(), new HashSet<>(attributeProtocols.getValue()));
239	            }
240	            protocols.put(protocolsEntry.getKey(), attributeProtocolsCopy);
241	        }
242	        preserveRelativeLinks = copy.preserveRelativeLinks;
243	    }
