245	    /**
246	     Add a list of allowed elements to a safelist. (If a tag is not allowed, it will be removed from the HTML.)
247	
248	     @param tags tag names to allow
249	     @return this (for chaining)
250	     */
251	    public Safelist addTags(String... tags) {
252	        Validate.notNull(tags);
253	
254	        for (String tagName : tags) {
255	            Validate.notEmpty(tagName);
256	            Validate.isFalse(tagName.equalsIgnoreCase("noscript"),
257	                "noscript is unsupported in Safelists, due to incompatibilities between parsers with and without script-mode enabled");
258	            tagNames.add(TagName.valueOf(tagName));
259	        }
260	        return this;
261	    }
262	
263	    /**
264	     Remove a list of allowed elements from a safelist. (If a tag is not allowed, it will be removed from the HTML.)
265	
266	     @param tags tag names to disallow
267	     @return this (for chaining)
268	     */
269	    public Safelist removeTags(String... tags) {
270	        Validate.notNull(tags);
271	
272	        for(String tag: tags) {
273	            Validate.notEmpty(tag);
274	            TagName tagName = TagName.valueOf(tag);
275	
276	            if(tagNames.remove(tagName)) { // Only look in sub-maps if tag was allowed
277	                attributes.remove(tagName);
278	                enforcedAttributes.remove(tagName);
279	                protocols.remove(tagName);
280	            }
281	        }
282	        return this;
283	    }
