285	    /**
286	     Add a list of allowed attributes to a tag. (If an attribute is not allowed on an element, it will be removed.)
287	     <p>
288	     E.g.: <code>addAttributes("a", "href", "class")</code> allows <code>href</code> and <code>class</code> attributes
289	     on <code>a</code> tags.
290	     </p>
291	     <p>
292	     To make an attribute valid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
293	     <code>addAttributes(":all", "class")</code>.
294	     </p>
295	
296	     @param tag  The tag the attributes are for. The tag will be added to the allowed tag list if necessary.
297	     @param attributes List of valid attributes for the tag
298	     @return this (for chaining)
299	     */
300	    public Safelist addAttributes(String tag, String... attributes) {
301	        Validate.notEmpty(tag);
302	        Validate.notNull(attributes);
303	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
304	
305	        addTags(tag);
306	        TagName tagName = TagName.valueOf(tag);
307	        Set<AttributeKey> attributeSet = new HashSet<>();
308	        for (String key : attributes) {
309	            Validate.notEmpty(key);
310	            attributeSet.add(AttributeKey.valueOf(key));
311	        }
312	        Set<AttributeKey> currentSet = this.attributes.computeIfAbsent(tagName, k -> new HashSet<>());
313	        currentSet.addAll(attributeSet);
314	        return this;
315	    }
316	
317	    /**
318	     Remove a list of allowed attributes from a tag. (If an attribute is not allowed on an element, it will be removed.)
319	     <p>
320	     E.g.: <code>removeAttributes("a", "href", "class")</code> disallows <code>href</code> and <code>class</code>
321	     attributes on <code>a</code> tags.
322	     </p>
323	     <p>
324	     To make an attribute invalid for <b>all tags</b>, use the pseudo tag <code>:all</code>, e.g.
325	     <code>removeAttributes(":all", "class")</code>.
326	     </p>
327	
328	     @param tag  The tag the attributes are for.
329	     @param attributes List of invalid attributes for the tag
330	     @return this (for chaining)
331	     */
332	    public Safelist removeAttributes(String tag, String... attributes) {
333	        Validate.notEmpty(tag);
334	        Validate.notNull(attributes);
335	        Validate.isTrue(attributes.length > 0, "No attribute names supplied.");
336	
337	        TagName tagName = TagName.valueOf(tag);
338	        Set<AttributeKey> attributeSet = new HashSet<>();
339	        for (String key : attributes) {
340	            Validate.notEmpty(key);
341	            attributeSet.add(AttributeKey.valueOf(key));
342	        }
343	        if(tagNames.contains(tagName) && this.attributes.containsKey(tagName)) { // Only look in sub-maps if tag was allowed
344	            Set<AttributeKey> currentSet = this.attributes.get(tagName);
345	            currentSet.removeAll(attributeSet);
346	
347	            if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
348	                this.attributes.remove(tagName);
349	        }
350	        if(tag.equals(All)) { // Attribute needs to be removed from all individually set tags
351	            Iterator<Map.Entry<TagName, Set<AttributeKey>>> it = this.attributes.entrySet().iterator();
352	            while (it.hasNext()) {
353	                Map.Entry<TagName, Set<AttributeKey>> entry = it.next();
354	                Set<AttributeKey> currentSet = entry.getValue();
355	                currentSet.removeAll(attributeSet);
356	                if(currentSet.isEmpty()) // Remove tag from attribute map if no attributes are allowed for tag
357	                    it.remove();
358	            }
359	        }
360	        return this;
361	    }
362	
363	    /**
364	     Add an enforced attribute to a tag. An enforced attribute will always be added to the element. If the element
365	     already has the attribute set, it will be overridden with this value.
366	     <p>
367	     E.g.: <code>addEnforcedAttribute("a", "rel", "nofollow")</code> will make all <code>a</code> tags output as
368	     <code>&lt;a href="..." rel="nofollow"&gt;</code>
369	     </p>
370	
371	     @param tag   The tag the enforced attribute is for. The tag will be added to the allowed tag list if necessary.
372	     @param attribute   The attribute name
373	     @param value The enforced attribute value
374	     @return this (for chaining)
375	     */
376	    public Safelist addEnforcedAttribute(String tag, String attribute, String value) {
377	        Validate.notEmpty(tag);
378	        Validate.notEmpty(attribute);
379	        Validate.notEmpty(value);
380	
381	        TagName tagName = TagName.valueOf(tag);
382	        tagNames.add(tagName);
383	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
384	        AttributeValue attrVal = AttributeValue.valueOf(value);
385	
386	        Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.computeIfAbsent(tagName, k -> new HashMap<>());
387	        attrMap.put(attrKey, attrVal);
388	        return this;
389	    }
390	
391	    /**
392	     Remove a previously configured enforced attribute from a tag.
393	
394	     @param tag   The tag the enforced attribute is for.
395	     @param attribute   The attribute name
396	     @return this (for chaining)
397	     */
398	    public Safelist removeEnforcedAttribute(String tag, String attribute) {
399	        Validate.notEmpty(tag);
400	        Validate.notEmpty(attribute);
401	
402	        TagName tagName = TagName.valueOf(tag);
403	        if(tagNames.contains(tagName) && enforcedAttributes.containsKey(tagName)) {
404	            AttributeKey attrKey = AttributeKey.valueOf(attribute);
405	            Map<AttributeKey, AttributeValue> attrMap = enforcedAttributes.get(tagName);
406	            attrMap.remove(attrKey);
407	
408	            if(attrMap.isEmpty()) // Remove tag from enforced attribute map if no enforced attributes are present
409	                enforcedAttributes.remove(tagName);
410	        }
411	        return this;
412	    }
413	
414	    /**
415	     * Configure this Safelist to preserve relative links in an element's URL attribute, or convert them to absolute
416	     * links. By default, this is <b>false</b>: URLs will be  made absolute (e.g. start with an allowed protocol, like
417	     * e.g. {@code http://}.
418	     *
419	     * @param preserve {@code true} to allow relative links, {@code false} (default) to deny
420	     * @return this Safelist, for chaining.
421	     * @see #addProtocols
422	     */
423	    public Safelist preserveRelativeLinks(boolean preserve) {
424	        preserveRelativeLinks = preserve;
425	        return this;
426	    }
427	
428	    /**
429	     * Get the current setting for preserving relative links.
430	     * @return {@code true} if relative links are preserved, {@code false} if they are converted to absolute.
431	     */
432	    public boolean preserveRelativeLinks() {
433	        return preserveRelativeLinks;
434	    }
435	
436	    /**
437	     Add allowed URL protocols for an element's URL attribute. This restricts the possible values of the attribute to
438	     URLs with the defined protocol.
439	     <p>
440	     E.g.: <code>addProtocols("a", "href", "ftp", "http", "https")</code>
441	     </p>
442	     <p>
443	     To allow a link to an in-page URL anchor (i.e. <code>&lt;a href="#anchor"&gt;</code>, add a <code>#</code>:<br>
444	     E.g.: <code>addProtocols("a", "href", "#")</code>
445	     </p>
446	
447	     @param tag       Tag the URL protocol is for
448	     @param attribute       Attribute name
449	     @param protocols List of valid protocols
450	     @return this, for chaining
451	     */
452	    public Safelist addProtocols(String tag, String attribute, String... protocols) {
453	        Validate.notEmpty(tag);
454	        Validate.notEmpty(attribute);
455	        Validate.notNull(protocols);
456	
457	        TagName tagName = TagName.valueOf(tag);
458	        AttributeKey attrKey = AttributeKey.valueOf(attribute);
459	        Map<AttributeKey, Set<Protocol>> attrMap = this.protocols.computeIfAbsent(tagName, k -> new HashMap<>());
460	        Set<Protocol> protSet = attrMap.computeIfAbsent(attrKey, k -> new HashSet<>());
461	
462	        for (String protocol : protocols) {
463	            Validate.notEmpty(protocol);
464	            Protocol prot = Protocol.valueOf(protocol);
465	            protSet.add(prot);
466	        }
467	        return this;
468	    }
469	
470	    /**
471	     Remove allowed URL protocols for an element's URL attribute. If you remove all protocols for an attribute, that
472	     attribute will allow any protocol.
473	     <p>
474	     E.g.: <code>removeProtocols("a", "href", "ftp")</code>
475	     </p>
476	
477	     @param tag Tag the URL protocol is for
478	     @param attribute Attribute name
479	     @param removeProtocols List of invalid protocols
480	     @return this, for chaining
481	     */
482	    public Safelist removeProtocols(String tag, String attribute, String... removeProtocols) {
483	        Validate.notEmpty(tag);
484	        Validate.notEmpty(attribute);
485	        Validate.notNull(removeProtocols);
486	
487	        TagName tagName = TagName.valueOf(tag);
488	        AttributeKey attr = AttributeKey.valueOf(attribute);
489	
490	        // make sure that what we're removing actually exists; otherwise can open the tag to any data and that can
491	        // be surprising
492	        Validate.isTrue(protocols.containsKey(tagName), "Cannot remove a protocol that is not set.");
493	        Map<AttributeKey, Set<Protocol>> tagProtocols = protocols.get(tagName);
494	        Validate.isTrue(tagProtocols.containsKey(attr), "Cannot remove a protocol that is not set.");
495	
496	        Set<Protocol> attrProtocols = tagProtocols.get(attr);
497	        for (String protocol : removeProtocols) {
498	            Validate.notEmpty(protocol);
499	            attrProtocols.remove(Protocol.valueOf(protocol));
500	        }
501	
502	        if (attrProtocols.isEmpty()) { // Remove protocol set if empty
503	            tagProtocols.remove(attr);
504	            if (tagProtocols.isEmpty()) // Remove entry for tag if empty
505	                protocols.remove(tagName);
506	        }
507	        return this;
508	    }
509	
510	    /**
511	     * Test if the supplied tag is allowed by this safelist.
512	     * @param tag test tag
513	     * @return true if allowed
514	     */
515	    public boolean isSafeTag(String tag) {
516	        return tagNames.contains(TagName.valueOf(tag));
517	    }
518	
519	    /**
520	     * Test if the supplied attribute is allowed by this safelist for this tag.
521	     * <p>This method does not modify the input element or attribute.</p>
522	     * @param tagName tag to consider allowing the attribute in
523	     * @param el element under test, to confirm protocol
524	     * @param attr attribute under test
525	     * @return true if allowed
526	     */
527	    public boolean isSafeAttribute(String tagName, Element el, Attribute attr) {
528	        TagName tag = TagName.valueOf(tagName);
529	        AttributeKey key = AttributeKey.valueOf(attr.getKey());
530	
531	        Set<AttributeKey> okSet = attributes.get(tag);
532	        if (okSet != null && okSet.contains(key)) {
533	            if (protocols.containsKey(tag)) {
534	                Map<AttributeKey, Set<Protocol>> attrProts = protocols.get(tag);
535	                // ok if not defined protocol; otherwise test
536	                return !attrProts.containsKey(key) || isSafeAttributeProtocol(el, attr, attrProts.get(key));
537	            } else { // attribute found, no protocols defined, so OK
538	                return true;
539	            }
540	        }
541	        Map<AttributeKey, AttributeValue> enforcedSet = enforcedAttributes.get(tag);
542	        if (enforcedSet != null && enforcedSet.containsKey(key)) {
543	            // enforced attr key was LCed via AttributeKey.valueOf(attr.getKey()),
544	            // if the input already has that exact value, treat it as safe
545	            return enforcedSet.get(key).equals(AttributeValue.valueOf(attr.getValue()));
546	        }
547	        // no attributes defined for tag, try :all tag
548	        return !tagName.equals(All) && isSafeAttribute(All, el, attr);
549	    }
550	
551	    /**
552	     Test that every URL candidate carried by the attribute value uses an allowed protocol. Single-valued URL
553	     attributes have one candidate; comma-separated attributes such as {@code srcset} may carry several, and a single
554	     dangerous candidate must not be smuggled through beside safe ones.
555	     */
556	    private boolean isSafeAttributeProtocol(Element el, Attribute attr, Set<Protocol> protocols) {
557	        String baseUri = el == null ? "" : el.baseUri();
558	        String value = attr.getValue();
559	        if (multiValueUrlAttribute(attr.getKey())) {
560	            int len = value.length();
561	            int start = 0;
562	            boolean found = false;
563	            for (int i = 0; i <= len; i++) {
564	                if (i == len || value.charAt(i) == ',') {
565	                    String candidate = stripCandidateDescriptor(value.substring(start, i));
566	                    if (!candidate.isEmpty()) {
567	                        if (!isSafeUrlCandidate(candidate, protocols, baseUri)) return false;
568	                        found = true;
569	                    }
570	                    start = i + 1;
571	                }
572	            }
573	            return found; // an empty value has no candidates to enforce a protocol on
574	        }
575	        return isSafeUrlCandidate(value, protocols, baseUri);
576	    }
577	
578	    /**
579	     Validate one URL candidate against the allowed protocol set. The candidate's own (trimmed) value determines its
580	     scheme -- a resolved absolute URL is never trusted to vouch for a different raw spelling, because in
581	     preserve-relative-links mode the raw value is what gets emitted.
582	     */
583	    private boolean isSafeUrlCandidate(String raw, Set<Protocol> protocols, String baseUri) {
584	        // ignore the leading/trailing ASCII whitespace (SP, TAB, LF, CR, FF) that browsers also strip from URLs
585	        int start = 0;
586	        int end = raw.length();
587	        while (start < end && isHtmlWhitespace(raw.charAt(start))) start++;
588	        while (end > start && isHtmlWhitespace(raw.charAt(end - 1))) end--;
589	        if (start == end) return false;
590	        String value = raw.substring(start, end);
591	
592	        // Per RFC 3986 a scheme is terminated by the first ':' that precedes any '/', '?' or '#'.
593	        int colon = -1;
594	        for (int i = 0; i < value.length(); i++) {
595	            char c = value.charAt(i);
596	            if (c == ':') { colon = i; break; }
597	            if (c == '/' || c == '?' || c == '#') break; // path/query/fragment starts first: no scheme
598	        }
599	
600	        if (colon > 0) {
601	            String scheme = value.substring(0, colon);
602	            if (isSchemeGrammar(scheme)) {
603	                for (Protocol protocol : protocols) {
604	                    String prot = protocol.toString();
605	                    if (prot.equals("#")) continue;
606	                    // exact ASCII scheme match, and the value must actually resolve, so a hostless "https:/foo"
607	                    // against a mismatched base is still dropped
608	                    if (isAllowedScheme(scheme, prot) && !StringUtil.resolve(baseUri, value).isEmpty()) return true;
609	                }
610	                return false; // a well-formed but disallowed scheme (javascript:, data:, vbscript: ...)
611	            }
612	            if (hasSmuggledSchemeBytes(scheme)) {
613	                // not a valid scheme but carrying scheme-smuggling bytes -- percent escapes ("%6Aavascript:" /
614	                // "java%73cript:"), backslashes, embedded whitespace / control / non-ASCII characters. Fail closed
615	                // rather than silently resolving it as a (possibly browser-rewritten) relative URL.
616	                return false;
617	            }
618	            // otherwise (e.g. "123:45") it is a relative reference; fall through to resolution
619	        }
620	
621	        // no scheme: an in-page anchor, or a relative reference resolved against the base URI
622	        for (Protocol protocol : protocols) {
623	            if (protocol.toString().equals("#") && isValidAnchor(value)) return true;
624	        }
625	        if (!isSafeRelativeReference(value)) return false; // malformed: control/format/Unicode-whitespace characters
626	        String resolved = StringUtil.resolve(baseUri, value);
627	        if (resolved.isEmpty()) return false; // unresolvable relative link (e.g. no base URI configured)
628	        int resolvedColon = resolved.indexOf(':');
629	        if (resolvedColon <= 0) return false;
630	        String resolvedScheme = resolved.substring(0, resolvedColon);
631	        for (Protocol protocol : protocols) {
632	            String prot = protocol.toString();
633	            if (!prot.equals("#") && isAllowedScheme(resolvedScheme, prot)) return true;
634	        }
635	        return false;
636	    }
637	
638	    /**
639	     A scheme-less reference is rejected when it carries ASCII control characters (C0 / DEL), Unicode formatting
640	     characters (such as bidi controls or zero-width spaces), or Unicode line/paragraph/space separators; ordinary
641	     spaces and percent-encoding in a path or query are still allowed. Anything else is resolved as a relative URL.
642	     */
643	    private static boolean isSafeRelativeReference(String value) {
644	        for (int i = 0; i < value.length(); i++) {
645	            char c = value.charAt(i);
646	            if (c < ' ' || c == 0x7f) return false; // C0 controls and DEL (ordinary space 0x20 is permitted)
647	            if (c > 0x7f) {
648	                int type = Character.getType(c);
649	                if (type == Character.CONTROL || type == Character.FORMAT
650	                    || type == Character.SPACE_SEPARATOR || type == Character.LINE_SEPARATOR
651	                    || type == Character.PARAGRAPH_SEPARATOR) return false;
652	            }
653	        }
654	        return true;
655	    }
656	
657	    private static boolean isAsciiAlpha(char c) {
658	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
659	    }
660	
661	    /**
662	     Detects bytes that are never legal inside an RFC 3986 scheme but are routinely used to disguise a scheme so a
663	     browser decodes or strips it after validation: percent escapes, backslashes, ASCII whitespace/control
664	     characters, or any non-ASCII character (including Unicode whitespace and formatting marks).
665	     */
666	    private static boolean hasSmuggledSchemeBytes(String scheme) {
667	        for (int i = 0; i < scheme.length(); i++) {
668	            char c = scheme.charAt(i);
669	            if (c == '%' || c == '\\' || c <= ' ' || c == 0x7f || c > 0x7e) return true;
670	        }
671	        return false;
672	    }
673	
674	    /** RFC 3986 scheme grammar: ALPHA *( ALPHA / DIGIT / "+" / "-" / "." ). */
675	    private static boolean isSchemeGrammar(String scheme) {
676	        int len = scheme.length();
677	        if (len == 0 || !isAsciiAlpha(scheme.charAt(0))) return false;
678	        for (int i = 1; i < len; i++) {
679	            char c = scheme.charAt(i);
680	            if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
681	                || c == '+' || c == '-' || c == '.')) return false;
682	        }
683	        return true;
684	    }
685	
686	    /** ASCII-case-insensitive match of a scheme that is already known to satisfy {@link #isSchemeGrammar}. */
687	    private static boolean isAllowedScheme(String scheme, String allowed) {
688	        int len = scheme.length();
689	        if (len != allowed.length()) return false;
690	        for (int i = 0; i < len; i++) {
691	            char c = scheme.charAt(i);
692	            if (c >= 'A' && c <= 'Z') c = (char) (c + ('a' - 'A')); // ASCII case folding only
693	            if (c != allowed.charAt(i)) return false;
694	        }
695	        return true;
696	    }
697	
698	    private static boolean isHtmlWhitespace(char c) {
699	        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f';
700	    }
701	
702	    /**
703	     URL attributes whose value may contain a comma-separated list of candidate URLs (each optionally followed by a
704	     whitespace and a descriptor). Every candidate is validated independently.
705	     */
706	    static boolean multiValueUrlAttribute(String key) {
707	        String lc = Normalizer.lowerCase(key);
708	        return lc.equals("srcset") || lc.equals("imagesrcset");
709	    }
710	
711	    /** For a srcset candidate ("url 1x" or "url 200w"), returns just the URL portion. */
712	    private static String stripCandidateDescriptor(String candidate) {
713	        int len = candidate.length();
714	        int i = 0;
715	        while (i < len && isHtmlWhitespace(candidate.charAt(i))) i++;
716	        int start = i;
717	        while (i < len && !isHtmlWhitespace(candidate.charAt(i))) i++;
718	        return candidate.substring(start, i);
719	    }
720	
721	    /**
722	     Check if a URL attribute should be normalized to an absolute URL in the cleaned output. Uses the configured
723	     protocols for that tag+attribute pair, falling back to {@code :all} only if the tag does not define the
724	     attribute.
725	     */
726	    boolean shouldAbsUrl(String tagName, String attrKey) {
727	        if (preserveRelativeLinks) return false;
728	        return shouldAbsUrl(TagName.valueOf(tagName), AttributeKey.valueOf(attrKey));
729	    }
730	
731	    private boolean shouldAbsUrl(TagName tag, AttributeKey key) {
732	        Set<AttributeKey> allowedAttrs = attributes.get(tag);
733	        if (allowedAttrs != null && allowedAttrs.contains(key)) {
734	            Map<AttributeKey, Set<Protocol>> protocolsByAttr = protocols.get(tag);
735	            return protocolsByAttr != null && protocolsByAttr.containsKey(key);
736	        }
737	
738	        Map<AttributeKey, AttributeValue> enforcedAttrs = enforcedAttributes.get(tag);
739	        if (enforcedAttrs != null && enforcedAttrs.containsKey(key)) return false;
740	
741	        return !tag.equals(AllTag) && shouldAbsUrl(AllTag, key);
742	    }
743	
744	    private static boolean isValidAnchor(String value) {
745	        return value.startsWith("#") && !value.matches(".*\\s.*");
746	    }
747	
748	    /**
749	     Gets the Attributes that should be enforced for a given tag
750	     * @param tagName the tag
751	     * @return the attributes that will be enforced; empty if none are set for the given tag
752	     */
753	    public Attributes getEnforcedAttributes(String tagName) {
754	        Attributes attrs = new Attributes();
755	        TagName tag = TagName.valueOf(tagName);
756	        if (enforcedAttributes.containsKey(tag)) {
757	            Map<AttributeKey, AttributeValue> keyVals = enforcedAttributes.get(tag);
758	            for (Map.Entry<AttributeKey, AttributeValue> entry : keyVals.entrySet()) {
759	                attrs.put(entry.getKey().toString(), entry.getValue().toString());
760	            }
761	        }
762	        return attrs;
763	    }
764	    
765	    // named types for config. All just hold strings, but here for my sanity.
766	
767	    static class TagName extends TypedValue {
768	        TagName(String value) {
769	            super(value);
770	        }
771	
772	        static TagName valueOf(String value) {
773	            return new TagName(Normalizer.lowerCase(value));
774	        }
775	    }
776	
777	    static class AttributeKey extends TypedValue {
778	        AttributeKey(String value) {
779	            super(value);
780	        }
781	
782	        static AttributeKey valueOf(String value) {
783	            return new AttributeKey(Normalizer.lowerCase(value));
784	        }
785	    }
786	
787	    static class AttributeValue extends TypedValue {
788	        AttributeValue(String value) {
789	            super(value);
790	        }
791	
792	        static AttributeValue valueOf(String value) {
793	            return new AttributeValue(value);
794	        }
795	    }
796	
797	    static class Protocol extends TypedValue {
798	        Protocol(String value) {
799	            super(value);
800	        }
801	
802	        static Protocol valueOf(String value) {
803	            return new Protocol(value);
804	        }
805	    }
806	
807	    abstract static class TypedValue {
808	        private final String value;
809	
810	        TypedValue(String value) {
811	            Validate.notNull(value);
812	            this.value = value;
813	        }
814	
815	        @Override
816	        public int hashCode() {
817	            return value.hashCode();
818	        }
819	
820	        @Override
821	        public boolean equals(Object obj) {
822	            if (this == obj) return true;
823	            if (obj == null || getClass() != obj.getClass()) return false;
824	            TypedValue other = (TypedValue) obj;
825	            return Objects.equals(value, other.value);
826	        }
827	
828	        @Override
829	        public String toString() {
830	            return value;
831	        }
832	    }
833	}
