11	/**
12	 Regression tests for URL protocol enforcement in the {@link Cleaner} / {@link Safelist}: executable schemes must be
13	 blocked in every common disguise, per-attribute protocol sets must not leak into each other, multi-URL attributes
14	 such as {@code srcset} must have every candidate checked, and ordinary relative links must keep working.
15	 */
16	public class UrlProtocolCleaningTest {
17	    private static final String Base = "https://example.com/page/index.html";
18	
19	    private static Safelist linkSafelist() {
20	        return Safelist.none()
21	            .addTags("a", "p")
22	            .addAttributes("a", "href", "title", "src");
23	    }
