29	    @ParameterizedTest
30	    @ValueSource(strings = {
31	        "javascript:alert(1)",
32	        "JavaScript:alert(1)",
33	        "JAVASCRIPT:1",
34	        "JaVaScRiPt:alert(1)",
35	        "  javascript:1",            // leading SP
36	        "javascript:1  ",            // trailing SP
37	        "\tjavascript:1",            // leading TAB
38	        "\njavascript:1",            // leading LF
39	        "\rjavascript:1",            // leading CR
40	        "\fjavascript:1",            // leading FF
41	        "javascript:1\r\n",          // trailing CRLF
42	        " &#x09;javascript:1",       // entity-encoded TAB
43	        "java&#x09;script:1",        // control char inside the scheme
44	        "java&#x01;script:1",        // SOH inside the scheme
45	        "java&#x00;script:1",        // NUL inside the scheme
46	        "&#0013;ja&Tab;va&Tab;script&#0010;:alert(1)",
47	        "ja&Tab;script&colon;1",     // entity-encoded colon
48	        "javascript\\:1",            // backslash
49	        "javascript:\\\\alert(1)",
50	        "java%73cript:1",            // percent-encoded 's'
51	        "%6Aavascript:1",            // percent-encoded 'j'
52	        "java%6asCript:1",
53	        "java\u007fscript:1",        // DEL inside the scheme
54	        "java script:1",             // space inside the scheme
55	        "java\u00a0script:1",      // non-breaking space inside the scheme
56	        "java\u200bscript:1",      // zero-width space inside the scheme
57	        "java\u202escript:1",      // right-to-left override inside the scheme
58	        "data:text/html,evil",
59	        "DATA:text/html,evil",
60	        "vbscript:msgbox(1)",
61	        "file:///etc/passwd",
