63	    void dropsDangerousHref(String href) {
64	        String html = "<a href=\"" + href + "\">x</a>";
65	        assertEquals("<a>x</a>", Jsoup.clean(html, Base, httpHttps()));
66	        assertEquals("<a>x</a>", Jsoup.clean(html, httpHttps().preserveRelativeLinks(true)));
67	        assertFalse(Jsoup.isValid(html, httpHttps()));
68	    }
