70	    @ParameterizedTest
71	    @ValueSource(strings = {
72	        "https://example.com/a?b=1#c",
73	        "http://example.com/path",
74	        "https://example.com/:javascript:x",   // dangerous word later in the path is harmless
75	        "http://evil.com/a:b:c",
76	    })
77	    void keepsAllowedHrefWithPathQueryFragment(String href) {
78	        String out = Jsoup.clean("<a href=\"" + href + "\">x</a>", Base, httpHttps());
79	        assertEquals("<a href=\"" + href + "\">x</a>", out);
80	        assertTrue(Jsoup.isValid("<a href=\"" + href + "\">x</a>", httpHttps()));
81	    }
