83	    @Test void comparesSchemeAsciiCaseInsensitively() {
84	        assertEquals("<a href=\"https://Example.COM/x\">x</a>",
85	            Jsoup.clean("<a href=HTTPS://Example.COM/x>x</a>", Base, httpHttps()));
86	    }
87	
88	    @Test void keepsFullHrefSemantics() {
89	        assertEquals("<a href=\"https://example.com/a?b=1#c\">x</a>",
90	            Jsoup.clean("<a href=\"https://example.com/a?b=1#c\">x</a>", Base, httpHttps()));
91	    }
