93	    @ParameterizedTest
94	    @ValueSource(strings = {
95	        "foo/bar.html",
96	        "/foo/bar",
97	        "#section",
98	        "foo?a=1#b",
99	        "//cdn.example.com/x",       // protocol-relative
100	        "a/b:c",                     // colon in a later path segment
101	        "/foo:bar",
102	        "search?q=a:b",
103	        "123:45",                    // not a scheme (does not start with a letter) -> relative
104	    })
105	    void keepsRelativeLinksWhenConfigured(String href) {
106	        String out = Jsoup.clean("<a href=\"" + href + "\">x</a>", httpHttps().preserveRelativeLinks(true));
