package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.junit.jupiter.api.Test;

class ScratchProbeTest {
    private static final String Base = "https://example.com/page/index.html";

    private static Safelist sl() {
        return Safelist.none().addTags("a", "img", "form", "p")
            .addAttributes("a", "href", "src", "action", "title")
            .addAttributes("img", "src", "alt")
            .addAttributes("form", "action")
            .addProtocols("a", "href", "http", "https")
            .addProtocols("a", "src", "http", "https")
            .addProtocols("img", "src", "http", "https")
            .addProtocols("form", "action", "http", "https");
    }

    private void probe(String label, String raw) {
        try {
            String out = Jsoup.clean("<p><a href=\"" + raw + "\" src=\"https://safe.com/s\" title=t>" +
                "<img src=\"https://safe.com/i.png\" alt=im></a></p>", Base, sl());
            System.out.println(label + " => " + out);
        } catch (Exception e) {
            System.out.println(label + " => THREW " + e);
        }
    }

    @Test void probes() {
        probe("missing-host https", "https:///path");
        probe("missing-host http", "http://:80/");
        probe("multi colon abs", "https://h.com/a:b:c");
        probe("multi colon rel", "a:b:c");
        probe("bad ipv6", "https://[::1");
        probe("backslash scheme", "https:\\\\evil.com/x");
        probe("backslash relative", "foo\\\\bar");
        probe("tab inside url", "https://h.com/a\tb");
        probe("newline in path", "/a\nb");
        probe("null-ish", "%00");
        probe("just colon", ":foo");
        probe("colon start", ":https://evil.com");
        probe("spaces around", "  https://h.com/  ");
        probe("query only", "?q=1");
        probe("fragment only", "#frag");
        probe("empty", "");
        probe("dot segments", "./../x");
        probe("proto relative", "//cdn.example.com/x");
        probe("encoded host", "https://ex%01ample.com/");
        probe("cr lf scheme", "ht\ntps://h.com/");
        probe("form action rel", null);
    }

    @Test void formProbe() {
        String[] vals = {"/submit", "//cdn.example.com/submit", "?x=1", "javascript:1",
            "https://h.com/a:b:c", "https:///nohost", "  https://h.com ", "a:b"};
        for (String v : vals) {
            try {
                System.out.println("form[" + v + "] => " +
                    Jsoup.clean("<form action=\"" + v + "\"></form>", Base, sl()));
            } catch (Exception e) {
                System.out.println("form[" + v + "] => THREW " + e);
            }
        }
    }
}

