package org.jsoup.safety;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ScratchProbeTest {
    private static final String Base = "https://example.com/page/index.html";

    private static Safelist sl() {
        return Safelist.none().addTags("a", "p")
            .addAttributes("a", "href", "title")
            .addProtocols("a", "href", "http", "https");
    }

    @Test void doesNotMutateCallerDocument() {
        Document dirty = Jsoup.parseBodyFragment(
            "<p>hi<a href=foo title=t>x</a><script>bad()</script></p>", Base);
        String before = dirty.body().html();
        Document clean = new Cleaner(Safelist.relaxed()).clean(dirty);
        assertEquals(before, dirty.body().html(), "source document must be untouched");
        assertNotEquals(before, clean.body().html());
    }

    @Test void repeatedCallsNoPollution() {
        Safelist s = sl();
        // first call: relative resolves against base A
        String a = Jsoup.clean("<a href=x>x</a>", "https://a.com/dir/index.html", s);
        assertEquals("<a href=\"https://a.com/dir/x\">x</a>", a);
        // second call with a different base must not see A
        String b = Jsoup.clean("<a href=x>x</a>", "https://b.org/", s);
        assertEquals("<a href=\"https://b.org/x\">x</a>", b);
        // back to base A
        String a2 = Jsoup.clean("<a href=x>x</a>", "https://a.com/dir/index.html", s);
        assertEquals(a, a2);
    }

    @Test void preserveThenResolveModes() {
        String html = "<a href=rel>x</a>";
        assertEquals("<a href=\"rel\">x</a>",
            Jsoup.clean(html, Base, sl().preserveRelativeLinks(true)));
        assertEquals("<a href=\"https://example.com/page/rel\">x</a>",
            Jsoup.clean(html, Base, sl()));
    }

    @Test void httpBaseInheritedByProtoRelative() {
        assertEquals("<a href=\"http://cdn.example.com/x\">x</a>",
            Jsoup.clean("<a href=//cdn.example.com/x>x</a>", "http://example.com/", sl()));
    }

    @Test void idempotentAcrossBases() {
        String once = Jsoup.clean("<a href=rel?q=1#f>x</a>", Base, sl());
        assertEquals(once, Jsoup.clean(once, Base, sl()));
        // feeding already-absolute output through a different base leaves it absolute
        assertEquals(once, Jsoup.clean(once, "https://other.net/", sl()));
    }
}

